    private final OrderStatus to;

    public IllegalStatusTransition(OrderStatus from, OrderStatus to) {
        super("cannot move order from " + from + " to " + to);
        this.from = from;
        this.to = to;
    }

    public OrderStatus from() { return from; }
    public OrderStatus to() { return to; }
}

